        if (size)
        {
            std::cerr << "[" << context << "] " << std::string_view(buffer, size) << std::endl;
        }
    }

    bool reportIfFailed(SlangResult result, const char *action, slang::IBlob *diagnostics)
    {
        if (SLANG_FAILED(result))
        {
            dumpDiagnostics(action, diagnostics);
            std::cerr << action << " failed with SlangResult=" << result << std::endl;
            return true;
        }
